CREATE SCHEMA IF NOT EXISTS truss; COMMENT ON SCHEMA truss IS 'truss-layout parallel-edge-1.0 candidate'; CREATE TABLE truss.setting (key text PRIMARY KEY, value jsonb NOT NULL); INSERT INTO truss.setting VALUES ('journal_mode', '"engine"'); INSERT INTO truss.setting VALUES ('key_reuse', '"forbid"'); CREATE TABLE truss.module_access (document_id text NOT NULL COLLATE pg_catalog."C", module text NOT NULL COLLATE pg_catalog."C", reader_role text NOT NULL COLLATE pg_catalog."C", writer_role text NOT NULL COLLATE pg_catalog."C", CONSTRAINT module_access_qualified_pk PRIMARY KEY (document_id, module), CONSTRAINT module_access_roles_differ CHECK (reader_role <> writer_role)); CREATE TABLE truss.schema_rev (rev int PRIMARY KEY, accepted_at timestamptz NOT NULL DEFAULT now(), origin jsonb NOT NULL DEFAULT ('{}'::jsonb), CONSTRAINT schema_rev_origin_is_object CHECK (jsonb_typeof(origin) = 'object')); INSERT INTO truss.schema_rev VALUES (0, now(), '{}'); CREATE TABLE truss.schema_head (id int PRIMARY KEY CHECK (id = 1), rev int NOT NULL REFERENCES truss.schema_rev (rev)); INSERT INTO truss.schema_head VALUES (1, 0); CREATE TABLE truss.schema_doc (rev int NOT NULL REFERENCES truss.schema_rev (rev), ord int NOT NULL, doc_id text NOT NULL, doc_revision text NOT NULL, umf_version text NOT NULL, content_sha256 text NOT NULL, document text NOT NULL, validation jsonb NOT NULL, PRIMARY KEY (rev, ord), UNIQUE (rev, doc_id)); CREATE TABLE truss.schema_change (rev int NOT NULL REFERENCES truss.schema_rev (rev), seq int NOT NULL, kind text NOT NULL CHECK (kind IN ('type', 'prop', 'rel')), def_id int NOT NULL, before jsonb NOT NULL, after jsonb NOT NULL, PRIMARY KEY (rev, seq)); CREATE TABLE truss.type_def (document_id text NOT NULL COLLATE pg_catalog."C", type_id int PRIMARY KEY, module text NOT NULL COLLATE pg_catalog."C", element text NOT NULL COLLATE pg_catalog."C", kind text NOT NULL, provisional boolean NOT NULL DEFAULT false, since_rev int NOT NULL REFERENCES truss.schema_rev (rev), doc_ord int, retired_rev int REFERENCES truss.schema_rev (rev), lineage_profile text NOT NULL COLLATE pg_catalog."C", lineage_bytes bytea NOT NULL, lineage_sha256 bytea GENERATED ALWAYS AS (pg_catalog.sha256(lineage_bytes)) STORED, CONSTRAINT type_def_lineage_profile_nonempty CHECK (octet_length(lineage_profile) > 0), CONSTRAINT type_def_lineage_bytes_nonempty CHECK (octet_length(lineage_bytes) > 0), FOREIGN KEY (since_rev, doc_ord) REFERENCES truss.schema_doc (rev, ord)); CREATE TABLE truss.prop_def (prop_id int PRIMARY KEY, type_id int NOT NULL REFERENCES truss.type_def (type_id), element text NOT NULL, name text NOT NULL, scalar_type text, nullability text NOT NULL, cardinality text NOT NULL, facets jsonb, item jsonb, home text NOT NULL DEFAULT 'json' CHECK (home IN ('json', 'row')), since_rev int NOT NULL REFERENCES truss.schema_rev (rev), doc_ord int NOT NULL, retired_rev int REFERENCES truss.schema_rev (rev), UNIQUE (type_id, name), UNIQUE (type_id, element), FOREIGN KEY (since_rev, doc_ord) REFERENCES truss.schema_doc (rev, ord)); CREATE TABLE truss.key_def (type_id int NOT NULL REFERENCES truss.type_def (type_id), key_id text NOT NULL, key_num smallint NOT NULL, prop_ids int[] NOT NULL, is_primary boolean NOT NULL, since_rev int NOT NULL REFERENCES truss.schema_rev (rev), retired_rev int REFERENCES truss.schema_rev (rev), PRIMARY KEY (type_id, key_id), UNIQUE (type_id, key_num)); CREATE TABLE truss.rel_def (document_id text NOT NULL COLLATE pg_catalog."C", rel_type_id int PRIMARY KEY, module text NOT NULL COLLATE pg_catalog."C", rel_id text NOT NULL COLLATE pg_catalog."C", name text NOT NULL, source_min int NOT NULL, source_max int, target_min int NOT NULL, target_max int, lifecycle text NOT NULL, directed boolean NOT NULL, target_key text, composition boolean NOT NULL DEFAULT false, assoc_type_id int REFERENCES truss.type_def (type_id), inverse text, since_rev int NOT NULL REFERENCES truss.schema_rev (rev), doc_ord int NOT NULL, retired_rev int REFERENCES truss.schema_rev (rev), FOREIGN KEY (since_rev, doc_ord) REFERENCES truss.schema_doc (rev, ord)); CREATE TABLE truss.rel_endpoint (rel_type_id int NOT NULL REFERENCES truss.rel_def (rel_type_id), source_type int NOT NULL REFERENCES truss.type_def (type_id), target_type int NOT NULL REFERENCES truss.type_def (type_id), PRIMARY KEY (rel_type_id, source_type, target_type)); CREATE SEQUENCE truss.id_seq; CREATE TABLE truss.object (id bigint NOT NULL DEFAULT nextval('truss.id_seq'), type_id int NOT NULL REFERENCES truss.type_def (type_id), props jsonb NOT NULL DEFAULT ('{}'::jsonb), retained jsonb, root_id bigint, root_type int, rev int NOT NULL REFERENCES truss.schema_rev (rev), ver bigint NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), updated_at timestamptz NOT NULL DEFAULT clock_timestamp(), CONSTRAINT object_pkey PRIMARY KEY (id, type_id), CONSTRAINT object_props_is_object CHECK (jsonb_typeof(props) = 'object'), CONSTRAINT object_retained_is_object CHECK (retained IS NULL OR jsonb_typeof(retained) = 'object'), CONSTRAINT object_root_both_or_neither CHECK ((root_id IS NULL) = (root_type IS NULL)), CONSTRAINT object_root_fk FOREIGN KEY (root_id, root_type) REFERENCES truss.object (id, type_id) ON DELETE RESTRICT); CREATE INDEX object_type_id ON truss.object USING btree (type_id, id); CREATE TABLE truss.edge (id bigint PRIMARY KEY DEFAULT nextval('truss.id_seq'), rel_type_id int NOT NULL, source_id bigint NOT NULL, source_type int NOT NULL, target_id bigint NOT NULL, target_type int NOT NULL, props jsonb NOT NULL DEFAULT ('{}'::jsonb), order_key text COLLATE "C", rev int NOT NULL REFERENCES truss.schema_rev (rev), ver bigint NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), updated_at timestamptz NOT NULL DEFAULT clock_timestamp(), CONSTRAINT edge_props_is_object CHECK (jsonb_typeof(props) = 'object'), CONSTRAINT edge_source_fk FOREIGN KEY (source_id, source_type) REFERENCES truss.object (id, type_id) ON DELETE RESTRICT, CONSTRAINT edge_target_fk FOREIGN KEY (target_id, target_type) REFERENCES truss.object (id, type_id) ON DELETE RESTRICT, CONSTRAINT edge_endpoint_types_fk FOREIGN KEY (rel_type_id, source_type, target_type) REFERENCES truss.rel_endpoint (rel_type_id, source_type, target_type)); CREATE INDEX edge_out ON truss.edge USING btree (source_id, rel_type_id, target_id) INCLUDE (target_type); CREATE INDEX edge_in ON truss.edge USING btree (target_id, rel_type_id) INCLUDE (source_id, source_type); CREATE TABLE truss.edge_limit (rel_type_id bigint NOT NULL, side char(1) NOT NULL CHECK (side IN ('s', 't')), endpoint_id bigint NOT NULL, edge_id bigint NOT NULL REFERENCES truss.edge (id) ON DELETE CASCADE, PRIMARY KEY (rel_type_id, side, endpoint_id)); CREATE INDEX edge_limit_edge ON truss.edge_limit USING btree (edge_id); CREATE TABLE truss.key_tombstone (entity_kind char(1) NOT NULL CHECK (entity_kind IN ('e')), type_id int NOT NULL, key_num smallint NOT NULL, k text NOT NULL COLLATE "C", entity_id bigint NOT NULL, ver bigint NOT NULL, at timestamptz NOT NULL DEFAULT clock_timestamp(), PRIMARY KEY (entity_kind, type_id, key_num, k), CONSTRAINT key_tombstone_edge_key CHECK (entity_kind = 'o' OR key_num = 0)); CREATE TABLE truss.record_source (entity_kind char(1) NOT NULL CHECK (entity_kind IN ('o', 'e')), entity_id bigint NOT NULL, load_id text NOT NULL, source jsonb NOT NULL DEFAULT ('{}'::jsonb), imported_at timestamptz NOT NULL DEFAULT clock_timestamp(), PRIMARY KEY (entity_kind, entity_id), CONSTRAINT record_source_is_object CHECK (jsonb_typeof(source) = 'object')); CREATE INDEX record_source_load ON truss.record_source USING btree (load_id); CREATE SEQUENCE truss.journal_seq AS bigint INCREMENT 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 1 NO CYCLE CACHE 1; CREATE TABLE truss.journal (seq bigint NOT NULL DEFAULT nextval('truss.journal_seq'), at timestamptz NOT NULL DEFAULT clock_timestamp(), xid xid8 NOT NULL DEFAULT pg_current_xact_id(), entity_kind char(1) NOT NULL CHECK (entity_kind IN ('o', 'e')), entity_id bigint NOT NULL, entity_type int NOT NULL, ver bigint NOT NULL, op text NOT NULL CHECK (op IN ('create', 'update', 'delete', 'retain', 'rebind', 'transform', 'metadata')), prop_id int, old_value jsonb, new_value jsonb, rev int NOT NULL, origin jsonb NOT NULL DEFAULT ('{}'::jsonb), CONSTRAINT journal_pkey PRIMARY KEY (at, seq), CONSTRAINT journal_origin_is_object CHECK (jsonb_typeof(origin) = 'object')) PARTITION BY RANGE(at); CREATE INDEX journal_entity ON truss.journal USING btree (entity_kind, entity_id, ver); CREATE INDEX journal_feed ON truss.journal USING btree (xid, seq); CREATE INDEX journal_request ON truss.journal USING btree ((origin #>> '{request,id}')) WHERE origin ? 'request'; ALTER TABLE truss.edge ADD COLUMN retained pg_catalog.jsonb; ALTER TABLE truss.edge ADD CONSTRAINT edge_retained_is_object CHECK (retained IS NULL OR pg_catalog.jsonb_typeof(retained) = 'object'); ALTER TABLE truss.journal ADD CONSTRAINT journal_complete_payload CHECK (old_value IS NULL AND new_value IS NOT NULL AND (pg_catalog.jsonb_typeof(new_value) = 'object' AND (new_value ->> 'interfaceVersion') = 'truss-journal-exact-bytes/0.2.0-proposal' AND (new_value ->> 'component') = 'event') IS TRUE); ALTER TABLE truss.journal ADD CONSTRAINT journal_complete_origin CHECK ((pg_catalog.jsonb_typeof(origin) = 'object' AND (origin ->> 'interfaceVersion') = 'truss-journal-exact-bytes/0.2.0-proposal' AND (origin ->> 'component') = 'origin') IS TRUE); ALTER TABLE truss.journal ADD CONSTRAINT journal_complete_property_mapping CHECK (((op IN ('update', 'transform', 'rebind') AND prop_id IS NOT NULL) OR (op IN ('create', 'delete', 'retain', 'metadata') AND prop_id IS NULL)) IS TRUE); ALTER TABLE truss.journal ADD CONSTRAINT journal_complete_positive_identity CHECK (entity_id > 0 AND ver > 0 AND seq > 0); CREATE INDEX type_def_lineage_route ON truss.type_def USING btree (lineage_sha256, type_id); ALTER TABLE truss.prop_def ADD CONSTRAINT prop_def_owner_property_row_home UNIQUE (type_id, prop_id); ALTER TABLE truss.edge ADD CONSTRAINT edge_typed_identity_row_home UNIQUE (id, rel_type_id); CREATE TABLE truss.relationship_lineage (rel_type_id int PRIMARY KEY REFERENCES truss.rel_def (rel_type_id) ON DELETE RESTRICT, lineage_category text NOT NULL, identity_profile text NOT NULL, original_identity_bytes bytea NOT NULL, identity_sha256 bytea GENERATED ALWAYS AS (pg_catalog.sha256(original_identity_bytes)) STORED, CONSTRAINT relationship_lineage_category CHECK (lineage_category IN ('authored', 'composition_field')), CONSTRAINT relationship_lineage_profile_nonempty CHECK (length(identity_profile) > 0), CONSTRAINT relationship_lineage_identity_nonempty CHECK (octet_length(original_identity_bytes) > 0)); CREATE INDEX relationship_lineage_route ON truss.relationship_lineage USING btree (identity_sha256, rel_type_id); ALTER TABLE truss.schema_doc ALTER COLUMN doc_id TYPE text COLLATE pg_catalog."C"; ALTER TABLE truss.schema_doc ADD CONSTRAINT schema_doc_definition_source_tuple UNIQUE (rev, ord, doc_id); ALTER TABLE truss.type_def ADD COLUMN definition_source_kind text COLLATE pg_catalog."C", ADD COLUMN definition_rev int, ADD COLUMN definition_doc_ord int, ADD COLUMN definition_document_id text COLLATE pg_catalog."C", ADD COLUMN binding_source_rev int, ADD COLUMN binding_source_pointer text COLLATE pg_catalog."C", ADD COLUMN binding_source_bytes bytea, ADD CONSTRAINT type_def_definition_document_fk FOREIGN KEY (definition_rev, definition_doc_ord, definition_document_id) REFERENCES truss.schema_doc (rev, ord, doc_id), ADD CONSTRAINT type_def_definition_binding_revision_fk FOREIGN KEY (binding_source_rev) REFERENCES truss.schema_rev (rev), ADD CONSTRAINT type_def_definition_source_complete CHECK ((provisional AND definition_source_kind IS NULL AND definition_rev IS NULL AND definition_doc_ord IS NULL AND definition_document_id IS NULL AND binding_source_rev IS NULL AND binding_source_pointer IS NULL AND binding_source_bytes IS NULL) OR (NOT provisional AND (definition_source_kind IS NOT NULL AND ((definition_source_kind = 'accepted_document' AND definition_rev IS NOT NULL AND definition_doc_ord IS NOT NULL AND definition_document_id IS NOT NULL AND binding_source_rev IS NULL AND binding_source_pointer IS NULL AND binding_source_bytes IS NULL) OR (definition_source_kind = 'accepted_binding' AND definition_rev IS NULL AND definition_doc_ord IS NULL AND definition_document_id IS NULL AND binding_source_rev IS NOT NULL AND binding_source_pointer IS NOT NULL AND binding_source_bytes IS NOT NULL AND octet_length(binding_source_bytes) > 0))))); ALTER TABLE truss.prop_def ADD COLUMN definition_source_kind text COLLATE pg_catalog."C", ADD COLUMN definition_rev int, ADD COLUMN definition_doc_ord int, ADD COLUMN definition_document_id text COLLATE pg_catalog."C", ADD COLUMN binding_source_rev int, ADD COLUMN binding_source_pointer text COLLATE pg_catalog."C", ADD COLUMN binding_source_bytes bytea, ADD CONSTRAINT prop_def_definition_document_fk FOREIGN KEY (definition_rev, definition_doc_ord, definition_document_id) REFERENCES truss.schema_doc (rev, ord, doc_id), ADD CONSTRAINT prop_def_definition_binding_revision_fk FOREIGN KEY (binding_source_rev) REFERENCES truss.schema_rev (rev), ADD CONSTRAINT prop_def_definition_source_complete CHECK (definition_source_kind IS NOT NULL AND ((definition_source_kind = 'accepted_document' AND definition_rev IS NOT NULL AND definition_doc_ord IS NOT NULL AND definition_document_id IS NOT NULL AND binding_source_rev IS NULL AND binding_source_pointer IS NULL AND binding_source_bytes IS NULL) OR (definition_source_kind = 'accepted_binding' AND definition_rev IS NULL AND definition_doc_ord IS NULL AND definition_document_id IS NULL AND binding_source_rev IS NOT NULL AND binding_source_pointer IS NOT NULL AND binding_source_bytes IS NOT NULL AND octet_length(binding_source_bytes) > 0))); ALTER TABLE truss.key_def ADD COLUMN definition_source_kind text COLLATE pg_catalog."C", ADD COLUMN definition_rev int, ADD COLUMN definition_doc_ord int, ADD COLUMN definition_document_id text COLLATE pg_catalog."C", ADD COLUMN binding_source_rev int, ADD COLUMN binding_source_pointer text COLLATE pg_catalog."C", ADD COLUMN binding_source_bytes bytea, ADD CONSTRAINT key_def_definition_document_fk FOREIGN KEY (definition_rev, definition_doc_ord, definition_document_id) REFERENCES truss.schema_doc (rev, ord, doc_id), ADD CONSTRAINT key_def_definition_binding_revision_fk FOREIGN KEY (binding_source_rev) REFERENCES truss.schema_rev (rev), ADD CONSTRAINT key_def_definition_source_complete CHECK (definition_source_kind IS NOT NULL AND ((definition_source_kind = 'accepted_document' AND definition_rev IS NOT NULL AND definition_doc_ord IS NOT NULL AND definition_document_id IS NOT NULL AND binding_source_rev IS NULL AND binding_source_pointer IS NULL AND binding_source_bytes IS NULL) OR (definition_source_kind = 'accepted_binding' AND definition_rev IS NULL AND definition_doc_ord IS NULL AND definition_document_id IS NULL AND binding_source_rev IS NOT NULL AND binding_source_pointer IS NOT NULL AND binding_source_bytes IS NOT NULL AND octet_length(binding_source_bytes) > 0))); ALTER TABLE truss.rel_def ADD COLUMN definition_source_kind text COLLATE pg_catalog."C", ADD COLUMN definition_rev int, ADD COLUMN definition_doc_ord int, ADD COLUMN definition_document_id text COLLATE pg_catalog."C", ADD COLUMN binding_source_rev int, ADD COLUMN binding_source_pointer text COLLATE pg_catalog."C", ADD COLUMN binding_source_bytes bytea, ADD CONSTRAINT rel_def_definition_document_fk FOREIGN KEY (definition_rev, definition_doc_ord, definition_document_id) REFERENCES truss.schema_doc (rev, ord, doc_id), ADD CONSTRAINT rel_def_definition_binding_revision_fk FOREIGN KEY (binding_source_rev) REFERENCES truss.schema_rev (rev), ADD CONSTRAINT rel_def_definition_source_complete CHECK (definition_source_kind IS NOT NULL AND ((definition_source_kind = 'accepted_document' AND definition_rev IS NOT NULL AND definition_doc_ord IS NOT NULL AND definition_document_id IS NOT NULL AND binding_source_rev IS NULL AND binding_source_pointer IS NULL AND binding_source_bytes IS NULL) OR (definition_source_kind = 'accepted_binding' AND definition_rev IS NULL AND definition_doc_ord IS NULL AND definition_document_id IS NULL AND binding_source_rev IS NOT NULL AND binding_source_pointer IS NOT NULL AND binding_source_bytes IS NOT NULL AND octet_length(binding_source_bytes) > 0))); CREATE SEQUENCE truss.key_storage_row_seq AS bigint MINVALUE 1 MAXVALUE 9223372036854775807 START 1 NO CYCLE; CREATE TABLE truss.key_bucket_guard (namespace_sha256 bytea NOT NULL, key_sha256 bytea NOT NULL, generation bigint NOT NULL DEFAULT 0, CONSTRAINT key_bucket_guard_pkey PRIMARY KEY (namespace_sha256, key_sha256), CONSTRAINT key_bucket_namespace_digest_size CHECK (octet_length(namespace_sha256) = 32), CONSTRAINT key_bucket_key_digest_size CHECK (octet_length(key_sha256) = 32), CONSTRAINT key_bucket_generation_nonnegative CHECK (generation >= 0)); CREATE TABLE truss.object_key_bucket (storage_row_id bigint NOT NULL DEFAULT nextval('truss.key_storage_row_seq'), type_id int NOT NULL, key_num smallint NOT NULL, object_id bigint NOT NULL, namespace_bytes bytea NOT NULL, key_bytes bytea NOT NULL, original_context_bytes bytea NOT NULL, namespace_sha256 bytea GENERATED ALWAYS AS (pg_catalog.sha256(namespace_bytes)) STORED, key_sha256 bytea GENERATED ALWAYS AS (pg_catalog.sha256(key_bytes)) STORED, CONSTRAINT object_key_bucket_pkey PRIMARY KEY (storage_row_id), CONSTRAINT object_key_bucket_storage_id_positive CHECK (storage_row_id > 0), CONSTRAINT object_key_bucket_namespace_bound CHECK (octet_length(namespace_bytes) BETWEEN 1 AND 65536), CONSTRAINT object_key_bucket_key_bound CHECK (octet_length(key_bytes) BETWEEN 1 AND 1048576), CONSTRAINT object_key_bucket_context_nonempty CHECK (octet_length(original_context_bytes) > 0), CONSTRAINT object_key_bucket_one_per_object UNIQUE (object_id, type_id, key_num), CONSTRAINT object_key_bucket_definition_fk FOREIGN KEY (type_id, key_num) REFERENCES truss.key_def (type_id, key_num), CONSTRAINT object_key_bucket_object_fk FOREIGN KEY (object_id, type_id) REFERENCES truss.object (id, type_id) ON DELETE CASCADE, CONSTRAINT object_key_bucket_guard_fk FOREIGN KEY (namespace_sha256, key_sha256) REFERENCES truss.key_bucket_guard (namespace_sha256, key_sha256)); CREATE INDEX object_key_bucket_route ON truss.object_key_bucket USING btree (namespace_sha256, key_sha256, storage_row_id); CREATE TABLE truss.object_key_reservation_bucket (storage_row_id bigint NOT NULL DEFAULT nextval('truss.key_storage_row_seq'), namespace_bytes bytea NOT NULL, key_bytes bytea NOT NULL, original_reservation_bytes bytea NOT NULL, namespace_sha256 bytea GENERATED ALWAYS AS (pg_catalog.sha256(namespace_bytes)) STORED, key_sha256 bytea GENERATED ALWAYS AS (pg_catalog.sha256(key_bytes)) STORED, CONSTRAINT object_key_reservation_bucket_pkey PRIMARY KEY (storage_row_id), CONSTRAINT object_key_reservation_storage_id_positive CHECK (storage_row_id > 0), CONSTRAINT object_key_reservation_namespace_bound CHECK (octet_length(namespace_bytes) BETWEEN 1 AND 65536), CONSTRAINT object_key_reservation_key_bound CHECK (octet_length(key_bytes) BETWEEN 1 AND 1048576), CONSTRAINT object_key_reservation_original_nonempty CHECK (octet_length(original_reservation_bytes) > 0), CONSTRAINT object_key_reservation_guard_fk FOREIGN KEY (namespace_sha256, key_sha256) REFERENCES truss.key_bucket_guard (namespace_sha256, key_sha256)); CREATE INDEX object_key_reservation_bucket_route ON truss.object_key_reservation_bucket USING btree (namespace_sha256, key_sha256, storage_row_id); CREATE TABLE truss.catalog_acceptance_report (rev int PRIMARY KEY REFERENCES truss.schema_rev (rev), report_bytes pg_catalog.bytea NOT NULL, CONSTRAINT catalog_acceptance_report_positive_revision CHECK (rev > 0), CONSTRAINT catalog_acceptance_report_nonempty CHECK (pg_catalog.octet_length(report_bytes) > 0)); CREATE FUNCTION truss.catalog_global_high_water_v01() RETURNS TABLE (allocation_domain text, maximum_id text) LANGUAGE plpgsql VOLATILE SECURITY DEFINER PARALLEL unsafe SET search_path TO pg_catalog, pg_temp AS $$
BEGIN
  RETURN QUERY
  SELECT 'type_id'::text, GREATEST(COALESCE(MAX(t.type_id)::bigint, 0), 0)::text
  FROM truss.type_def AS t
  UNION ALL
  SELECT 'prop_id'::text, GREATEST(COALESCE(MAX(p.prop_id)::bigint, 0), 0)::text
  FROM truss.prop_def AS p
  UNION ALL
  SELECT 'rel_type_id'::text, GREATEST(COALESCE(MAX(r.rel_type_id)::bigint, 0), 0)::text
  FROM truss.rel_def AS r;
END
$$; REVOKE ALL ON FUNCTION truss.catalog_global_high_water_v01() FROM public; CREATE FUNCTION truss.catalog_key_high_water_v01(original_type_id int) RETURNS TABLE (owner_type_id text, maximum_key_num text) LANGUAGE plpgsql VOLATILE SECURITY DEFINER PARALLEL unsafe SET search_path TO pg_catalog, pg_temp AS $$
DECLARE
  retained_type_id int;
BEGIN
  IF original_type_id IS NULL THEN
    RAISE EXCEPTION 'missing original key owner' USING ERRCODE = '22023';
  END IF;
  SELECT t.type_id INTO STRICT retained_type_id
  FROM truss.type_def AS t WHERE t.type_id = original_type_id;
  RETURN QUERY
  SELECT retained_type_id::text,
         GREATEST(COALESCE(MAX(k.key_num)::bigint, 0), 0)::text
  FROM truss.key_def AS k WHERE k.type_id = retained_type_id;
END
$$; REVOKE ALL ON FUNCTION truss.catalog_key_high_water_v01(int) FROM public; CREATE TABLE truss.installation_marker (singleton_id smallint PRIMARY KEY CHECK (singleton_id = 1), marker_interface_version text NOT NULL CHECK (marker_interface_version = 'truss-bootstrap-marker/0.1.0') COLLATE pg_catalog."C", installation_id text NOT NULL UNIQUE COLLATE pg_catalog."C", layout_version text NOT NULL COLLATE pg_catalog."C", bundle_sha256 bytea NOT NULL CHECK (octet_length(bundle_sha256) = 32), inventory_profile text NOT NULL COLLATE pg_catalog."C", inventory_sha256 bytea NOT NULL CHECK (octet_length(inventory_sha256) = 32), database_identity text NOT NULL COLLATE pg_catalog."C", schema_name text NOT NULL COLLATE pg_catalog."C", installed_at timestamptz NOT NULL, installed_at_text text NOT NULL COLLATE pg_catalog."C", CONSTRAINT installation_marker_identity_bounds CHECK (char_length(installation_id) BETWEEN 1 AND 256 AND octet_length(installation_id) <= 1024 AND char_length(layout_version) BETWEEN 1 AND 256 AND char_length(inventory_profile) BETWEEN 1 AND 256 AND char_length(database_identity) BETWEEN 1 AND 1024 AND char_length(schema_name) BETWEEN 1 AND 256 AND char_length(installed_at_text) BETWEEN 1 AND 128)); CREATE SEQUENCE truss.installation_archive_row_seq AS bigint MINVALUE 1 MAXVALUE 9223372036854775807 START 1 NO CYCLE; CREATE TABLE truss.installation_archive (archive_row_id bigint PRIMARY KEY DEFAULT nextval('truss.installation_archive_row_seq'), installation_id text NOT NULL COLLATE pg_catalog."C", artifact_role text NOT NULL COLLATE pg_catalog."C", artifact_identity text NOT NULL COLLATE pg_catalog."C", artifact_bytes bytea NOT NULL, artifact_sha256 bytea GENERATED ALWAYS AS (pg_catalog.sha256(artifact_bytes)) STORED, artifact_identity_sha256 bytea NOT NULL CONSTRAINT installation_archive_identity_digest_exact CHECK (artifact_identity_sha256 = pg_catalog.sha256(pg_catalog.convert_to(artifact_identity, 'UTF8'))), CONSTRAINT installation_archive_row_positive CHECK (archive_row_id > 0), CONSTRAINT installation_archive_role CHECK (artifact_role IN ('bundle', 'expected_inventory', 'installed_inventory', 'input', 'marker')), CONSTRAINT installation_archive_identity_bound CHECK (octet_length(artifact_identity) BETWEEN 1 AND 65536), CONSTRAINT installation_archive_bytes_bound CHECK (octet_length(artifact_bytes) BETWEEN 1 AND 16777216), CONSTRAINT installation_archive_marker_fk FOREIGN KEY (installation_id) REFERENCES truss.installation_marker (installation_id) ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED); CREATE INDEX installation_archive_identity_route ON truss.installation_archive USING btree (installation_id, artifact_identity_sha256, archive_row_id); CREATE TABLE truss.request_receipt_route_guard (namespace_sha256 bytea NOT NULL CONSTRAINT rr_guard_namespace_digest CHECK (octet_length(namespace_sha256) = 32), request_sha256 bytea NOT NULL CONSTRAINT rr_guard_request_digest CHECK (octet_length(request_sha256) = 32), generation bigint NOT NULL CONSTRAINT rr_guard_generation CHECK (generation >= 0), CONSTRAINT rr_guard_pk PRIMARY KEY (namespace_sha256, request_sha256)); CREATE SEQUENCE truss.request_receipt_row_seq AS bigint MINVALUE 1 MAXVALUE 9223372036854775807 START 1 NO CYCLE; CREATE TABLE truss.request_receipt (storage_row_id bigint CONSTRAINT rr_receipt_pk PRIMARY KEY DEFAULT nextval('truss.request_receipt_row_seq'), namespace_identity_utf8 bytea NOT NULL CONSTRAINT rr_namespace_identity_bytes CHECK (octet_length(namespace_identity_utf8) BETWEEN 1 AND 65536), request_id_utf8 bytea NOT NULL CONSTRAINT rr_request_identity_bytes CHECK (octet_length(request_id_utf8) BETWEEN 1 AND 65536), original_writer_xid xid8 NOT NULL, original_writer_context_bytes bytea NOT NULL CONSTRAINT rr_writer_context_bytes CHECK (octet_length(original_writer_context_bytes) BETWEEN 1 AND 1048576), lifecycle_generation bigint NOT NULL CONSTRAINT rr_lifecycle_generation CHECK (lifecycle_generation >= 0), payload_state text NOT NULL CONSTRAINT rr_payload_state CHECK (payload_state IN ('complete', 'expired')), original_receipt_bytes bytea, expired_identity_bytes bytea, namespace_sha256 bytea GENERATED ALWAYS AS (pg_catalog.sha256(namespace_identity_utf8)) STORED, request_sha256 bytea GENERATED ALWAYS AS (pg_catalog.sha256(request_id_utf8)) STORED, CONSTRAINT request_receipt_positive_storage CHECK (storage_row_id > 0), CONSTRAINT request_receipt_payload_shape CHECK ((payload_state = 'complete' AND original_receipt_bytes IS NOT NULL AND octet_length(original_receipt_bytes) BETWEEN 1 AND 67108864 AND expired_identity_bytes IS NULL AND expiry_writer_xid IS NULL AND expiry_writer_context_bytes IS NULL) OR (payload_state = 'expired' AND original_receipt_bytes IS NULL AND expired_identity_bytes IS NOT NULL AND octet_length(expired_identity_bytes) BETWEEN 1 AND 1048576 AND expiry_writer_xid IS NOT NULL AND expiry_writer_context_bytes IS NOT NULL)), expiry_writer_xid xid8, expiry_writer_context_bytes bytea CONSTRAINT rr_expiry_writer_context_bytes CHECK (expiry_writer_context_bytes IS NULL OR octet_length(expiry_writer_context_bytes) BETWEEN 1 AND 1048576)); CREATE INDEX request_receipt_route ON truss.request_receipt USING btree (namespace_sha256, request_sha256, storage_row_id); ALTER TABLE truss.prop_def ADD COLUMN declaration_module text NOT NULL CHECK (octet_length(declaration_module) BETWEEN 1 AND 65536) COLLATE pg_catalog."C"; ALTER TABLE truss.prop_def DROP CONSTRAINT prop_def_type_id_element_key; ALTER TABLE truss.prop_def ADD CONSTRAINT prop_def_qualified_field UNIQUE (type_id, declaration_module, element); CREATE TABLE truss.source_epoch_registry (installation_id text NOT NULL COLLATE pg_catalog."C", source_epoch text NOT NULL COLLATE pg_catalog."C", target_incarnation text NOT NULL COLLATE pg_catalog."C", predecessor_epoch text COLLATE pg_catalog."C", transition_reason text NOT NULL COLLATE pg_catalog."C", profile_bytes bytea NOT NULL, evidence_bytes bytea NOT NULL, evidence_sha256 bytea GENERATED ALWAYS AS (pg_catalog.sha256(evidence_bytes)) STORED, PRIMARY KEY (installation_id, source_epoch), UNIQUE (source_epoch), FOREIGN KEY (installation_id) REFERENCES truss.installation_marker (installation_id), FOREIGN KEY (installation_id, predecessor_epoch) REFERENCES truss.source_epoch_registry (installation_id, source_epoch), CHECK (octet_length(source_epoch) BETWEEN 1 AND 256), CHECK (octet_length(target_incarnation) BETWEEN 1 AND 1024), CHECK (octet_length(profile_bytes) BETWEEN 1 AND 65536), CHECK (octet_length(evidence_bytes) BETWEEN 1 AND 1048576), CHECK (transition_reason IN ('initial', 'restore')), CHECK ((transition_reason = 'initial' AND predecessor_epoch IS NULL) OR (transition_reason = 'restore' AND predecessor_epoch IS NOT NULL)), CHECK (predecessor_epoch IS NULL OR predecessor_epoch <> source_epoch)); CREATE TABLE truss.source_epoch_current (singleton_id smallint PRIMARY KEY CHECK (singleton_id = 1), installation_id text NOT NULL COLLATE pg_catalog."C", source_epoch text NOT NULL COLLATE pg_catalog."C", FOREIGN KEY (installation_id, source_epoch) REFERENCES truss.source_epoch_registry (installation_id, source_epoch)); REVOKE ALL ON truss.source_epoch_registry, truss.source_epoch_current FROM public